import { esc,fmt,dateLabel,dayKey } from '../utils.js';
import { icon } from '../ui/icons.js';
import { button,empty } from '../ui/helpers.js';
import { healthReady,sessionTiming } from './bridge.js';
export function healthView(health={}) {
  const native=healthReady();
  if(!native)return `<details class="panel quiet-details" id="health-section"><summary>Apple Salud / Fitness</summary><p class="help">Esta versión web no puede vincularse con Salud/Fitness. Esta conexión requiere una app nativa de iPhone; no está disponible desde Safari ni al instalar la web.</p></details>`;
  return `<section class="panel health-panel" id="health-section"><div class="day-title"><div class="health-title"><span class="icon-tile">${icon('heart')}</span><div><p class="eyebrow">CONEXIONES</p><h2>Apple Salud y Fitness</h2></div></div><span class="pill">${native?'iPhone · HealthKit':'Requiere app de iPhone'}</span></div><p class="help">Guarda tus sesiones de fuerza de Ritmo en Salud y consulta los entrenamientos del Apple Watch que se hayan sincronizado con tu iPhone.</p>${native?`<div class="health-status" role="status">${health.loading?'Consultando Salud…':health.checked?(health.available?(health.writeAuthorized?'Guardado de entrenamientos autorizado.':'Guardado sin autorización. Puedes revisar los permisos.'):'Salud no está disponible en este dispositivo.'):'Conecta cuando quieras. Tú eliges los permisos.'}</div><div class="toolbar">${button('health-connect','Vincular / revisar permisos',' '+(health.loading?'disabled':''),'primary')}${button('health-read','Consultar últimos 30 días',' '+(health.loading?'disabled':''))}${button('health-clear','Ocultar datos consultados')}</div><p class="help">La lectura requiere tu permiso. Apple no comunica si lo has denegado: una lista vacía también puede indicar falta de acceso. Para revocarlo: Salud → tu perfil → Apps → Ritmo.</p>${health.error?`<p class="notice" role="alert">${esc(health.error)}</p>`:''}${health.workouts?healthWorkouts(health.workouts,health.watchOnly):''}`:`<p class="notice">Esta versión web no puede vincularse con Salud/Fitness. La conexión está preparada en el proyecto nativo de iOS y requiere compilarlo e instalarlo en un iPhone. Añadir la web a la pantalla de inicio no habilita HealthKit.</p>`}<details><summary>Privacidad y alcance</summary><p class="help">Solo se solicita leer y guardar entrenamientos. Los datos consultados se muestran temporalmente en esta pantalla, no se envían a un servidor ni se incluyen en copias de seguridad de Ritmo. Guardar una sesión es una acción manual desde el historial: revisa fecha, hora y duración. No se inventan calorías ni se importan series que Apple no proporciona.</p><p class="help">Si ya registraste la misma sesión con el Apple Watch, evita guardarla otra vez desde Ritmo. Borrar una sesión local no la elimina de Salud. Los entrenamientos de Salud se muestran por separado y no se suman al volumen de fuerza de Ritmo.</p></details></section>`;
}
export function healthWorkouts(workouts,watchOnly=false) {
  const list=watchOnly?workouts.filter(w=>w.isWatch):workouts;
  return `<div class="health-workouts"><div class="day-title"><h3>Entrenamientos de Salud</h3><label class="check"><input type="checkbox" id="health-watch-only" ${watchOnly?'checked':''}>Solo Apple Watch</label></div><p class="help">${list.length} sesiones · ${fmt(list.reduce((n,w)=>n+w.duration/60,0))} min · hasta 100 resultados recientes. Actualiza después de sincronizar el reloj.</p>${list.length?`<ul>${list.map(w=>`<li><span class="health-workout-symbol">${icon(w.isWatch?'watch':'train')}</span><div><strong>${esc(w.name)}</strong><p>${esc(new Date(w.start).toLocaleString('es-ES',{dateStyle:'medium',timeStyle:'short'}))} · ${fmt(w.duration/60)} min</p><small>${esc(w.source)}${w.isWatch?' · Apple Watch':''}${w.isRitmo?' · Ritmo':''}</small></div></li>`).join('')}</ul>`:empty('No hay entrenamientos visibles','Comprueba el filtro, los permisos de Salud y la sincronización de tu Apple Watch.')}</div>`;
}
export function healthExportForm(session) {
  const t=sessionTiming(session);
  return `<form data-form="health-export" data-id="${esc(session.id)}"><p class="eyebrow">APPLE SALUD · FUERZA</p><h2>Guardar en Salud</h2><p>${esc(session.name)} · ${esc(dateLabel(session.date))}</p><p class="help">Revisa los horarios reales. Las sesiones antiguas pueden no tener duración registrada.</p><div class="fields"><label>Fecha<input name="date" type="date" value="${esc(t.date)}" max="${dayKey()}" required></label><label>Hora de inicio<input name="time" type="time" value="${esc(t.time)}" required></label></div><label>Duración real <span class="unit">minutos</span><input name="minutes" type="number" min="1" max="360" step="1" value="${t.minutes}" inputmode="numeric" required></label><p class="notice">Si también registraste esta sesión con el Apple Watch, ya puede estar en Salud. No la dupliques. Solo se guarda el entrenamiento de fuerza con sus horarios, sin calorías estimadas ni detalles de las series.</p><button class="primary">Confirmar y guardar en Salud</button></form>`;
}
